vec3 image(in vec2 uv) {
    return texture(iChannel0, uv).xyz;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float ot = sin(iTime * .25) * .5 + .5;

    vec2 uv = fragCoord / iResolution.xy;
    vec2 texSize = vec2(textureSize(iChannel0, 0));
    vec2 texel = vec2(.005);
    //texel = texSize / iResolution.xy;
    //texel = vec2(ot);
    //texel = vec2(iMouse.x / iResolution.x);

    vec3 v00 = image(uv);

    vec3 v10 = image(uv + vec2(texel.x, 0.));
    vec3 v1m0 = image(uv - vec2(texel.x, 0.));

    vec3 v01 = image(uv + vec2(0., texel.y));
    vec3 v01m = image(uv - vec2(0., texel.y));

    vec3 v11 = image(uv + vec2(texel));
    vec3 vm11 = image(uv - vec2(texel));

    vec3 v1m1 = image(uv + vec2(-texel.x, texel.y));
    vec3 v11m = image(uv + vec2(texel.x, -texel.y));

    vec3 color = (v00 + v10 + v1m0 + v01 + v01m + v11 + vm11 + v1m1 + v11m) / 9.;
    if (uv.x > .5) {
        color = (v00 + v10 + v1m0 + v01 + v01m) / 5.;
        if (uv.x < .51) {
            color = vec3(0.);
        }
    }

    fragColor = vec4(color, 1.);
}
